@code {
    [Parameter] public EventCallback OnPasswordChanged { get; set; }

    private bool _expanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _saving;
    private string? _message;
    private bool _isError;

    private bool CanSubmit =>
        !_saving &&
        !string.IsNullOrWhiteSpace(_currentPassword) &&
        !string.IsNullOrWhiteSpace(_newPassword) &&
        _newPassword == _confirmPassword &&
        _newPassword.Length >= 6;

    private void ToggleExpanded() => _expanded = !_expanded;

    private async Task UpdatePassword()
    {
        if (!CanSubmit) return;

        _saving = true;
        _message = null;

        await OnPasswordChanged.InvokeAsync();

        _message = "Password updated successfully!";
        _isError = false;
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _saving = false;
    }
}

