toolArgs.file_text:
@using sv_5170e1df0aa04291af39cc3f418de00d.Services
@inject ISettingsService SettingsService

<div class="appearance-section">
    @if (_loading)
    {
        <div class="text-center py-4">
            <div class="spinner-border text-primary" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else
    {
        <h4 class="section-heading">Appearance</h4>

        @if (!string.IsNullOrEmpty(_message))
        {
            <div class="alert alert-success alert-dismissible fade show">
                @_message
                <button type="button" class="btn-close" @onclick="() => _message = null"></button>
            </div>
        }

        <div class="row">
            <div class="col-md-7">
                <!-- Theme -->
                <div class="card mb-3">
                    <div class="card-body">
                        <h6 class="card-title">Theme</h6>
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="theme"
                                       id="theme-@theme" value="@theme"
                                       checked="@(_theme == theme)"
                                       @onchange="() => _theme = theme" />
                                <label class="form-check-label" for="theme-@theme">@theme</label>
                            </div>
                        }
                    </div>
                </div>

                <!-- Font Size -->
                <div class="card mb-3">
                    <div class="card-body">
                        <h6 class="card-title">Font Size</h6>
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="fontSize"
                                       id="fs-@size" value="@size"
                                       checked="@(_fontSize == size)"
                                       @onchange="() => _fontSize = size" />
                                <label class="form-check-label" for="fs-@size">@size</label>
                            </div>
                        }
                    </div>
                </div>

                <!-- Language -->
                <div class="card mb-3">
                    <div class="card-body">
                        <h6 class="card-title">Language</h6>
                        <select class="form-select" @bind="_language">
                            @foreach (var lang in _languages)
                            {
                                <option value="@lang">@lang</option>
                            }
                        </select>
                    </div>
                </div>

                <!-- Compact Mode -->
                <div class="card mb-3">
                    <div class="card-body">
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" id="compactMode"
                                   checked="@_compactMode"
                                   @onchange="e => _compactMode = (bool)e.Value!" />
                            <label class="form-check-label" for="compactMode">
                                <strong>Compact Mode</strong>
                                <div class="text-muted small">Reduce spacing and padding throughout the interface</div>
                            </label>
                        </div>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@_saving">
                    @if (_saving)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Save
                </button>
            </div>

            <!-- Live Preview -->
            <div class="col-md-5">
                <div class="preview-panel @PreviewThemeClass" style="font-size: @PreviewFontSize;">
                    <div class="preview-header">
                        <strong>Preview</strong>
                    </div>
                    <div class="preview-body" style="@(_compactMode ? "padding: 0.5rem;" : "padding: 1rem;")">
                        <div class="preview-nav">
                            <span class="preview-nav-item active">Home</span>
                            <span class="preview-nav-item">Dashboard</span>
                            <span class="preview-nav-item">Settings</span>
                        </div>
                        <div class="preview-content">
                            <h6 style="margin-top: 0.75rem;">Welcome back!</h6>
                            <p class="preview-text">This is how your interface will look with the current settings.</p>
                            <button class="preview-btn">Sample Button</button>
                        </div>
                    </div>
                    <div class="preview-footer">
                        Theme: @_theme · Font: @_fontSize · @_language
                        @if (_compactMode) { <span> · Compact</span> }
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private bool _loading = true;
    private bool _saving;
    private string? _message;

    private static readonly string[] _languages =
        ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese", "Korean"];

    private string PreviewThemeClass => _theme switch
    {
        "Dark" => "preview-dark",
        "System" => "preview-system",
        _ => "preview-light"
    };

    private string PreviewFontSize => _fontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.1rem",
        _ => "0.95rem"
    };

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAppearance()
    {
        _saving = true;
        _message = null;
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _message = "Appearance settings saved!";
        _saving = false;
    }
}

.appearance-section .section-heading {
    margin-bottom: 1.5rem;
    font-weight: 600;
}

/* Preview panel */
.preview-panel {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
    transition: all 0.2s ease;
}

.preview-header {
    padding: 0.5rem 1rem;
    border-bottom: 1px solid;
    font-size: 0.8rem;
}

.preview-footer {
    padding: 0.4rem 1rem;
    border-top: 1px solid;
    font-size: 0.7rem;
}

/* Light theme preview */
.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-light .preview-header,
.preview-light .preview-footer {
    background: #f8f9fa;
    border-color: #dee2e6;
    color: #6c757d;
}

.preview-light .preview-nav-item {
    color: #495057;
}

.preview-light .preview-nav-item.active {
    color: #0d6efd;
    border-bottom-color: #0d6efd;
}

.preview-light .preview-btn {
    background: #0d6efd;
    color: white;
    border: none;
}

/* Dark theme preview */
.preview-dark {
    background: #1a1a2e;
    color: #e0e0e0;
}

.preview-dark .preview-header,
.preview-dark .preview-footer {
    background: #16213e;
    border-color: #2a2a4a;
    color: #8888aa;
}

.preview-dark .preview-nav-item {
    color: #9999bb;
}

.preview-dark .preview-nav-item.active {
    color: #6ea8fe;
    border-bottom-color: #6ea8fe;
}

.preview-dark .preview-text {
    color: #aaaacc;
}

.preview-dark .preview-btn {
    background: #6ea8fe;
    color: #1a1a2e;
    border: none;
}

/* System theme preview (split) */
.preview-system {
    background: linear-gradient(135deg, #ffffff 50%, #1a1a2e 50%);
    color: #212529;
}

.preview-system .preview-header,
.preview-system .preview-footer {
    background: linear-gradient(90deg, #f8f9fa 50%, #16213e 50%);
    border-color: #dee2e6;
    color: #6c757d;
}

.preview-system .preview-btn {
    background: #0d6efd;
    color: white;
    border: none;
}

/* Shared preview elements */
.preview-nav {
    display: flex;
    gap: 1rem;
    border-bottom: 1px solid #dee2e6;
    padding-bottom: 0.5rem;
    margin-bottom: 0.5rem;
}

.preview-nav-item {
    font-size: 0.8em;
    padding-bottom: 0.25rem;
    border-bottom: 2px solid transparent;
    cursor: default;
}

.preview-text {
    font-size: 0.85em;
    margin: 0.5rem 0;
}

.preview-btn {
    font-size: 0.75em;
    padding: 0.3rem 0.8rem;
    border-radius: 0.25rem;
    cursor: default;
}

